// Generated by the harness from scenarios/03-restart.json. Do not edit.
import XCTest

final class S03RestartSpec: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testRestartMidGame() {
        let scenario = Scenario(region: "en-US")
        scenario.launch(fresh: true)
        scenario.tap("square-0")
        scenario.tap("square-4")
        scenario.tap("restart-button")
        scenario.expectShows("square-0", "")
        scenario.expectShows("square-4", "")
        scenario.expectShows("turn", "X's turn")
        scenario.tap("square-4")
        scenario.expectShows("square-4", "X")
    }

    func testRestartAfterWin() {
        let scenario = Scenario(region: "en-US")
        scenario.launch(fresh: true)
        scenario.tap("square-0")
        scenario.tap("square-3")
        scenario.tap("square-1")
        scenario.tap("square-4")
        scenario.tap("square-2")
        scenario.expectShows("turn", "X wins!")
        scenario.tap("restart-button")
        scenario.expectShows("turn", "X's turn")
        scenario.expectShows("square-0", "")
        scenario.tap("square-5")
        scenario.expectShows("square-5", "X")
        scenario.expectShows("turn", "O's turn")
    }

    func testNothingSavedOnReopen() {
        let scenario = Scenario(region: "en-US")
        scenario.launch(fresh: true)
        scenario.tap("square-0")
        scenario.tap("square-1")
        scenario.expectShows("turn", "X's turn")
        scenario.restart()
        scenario.expectShows("square-0", "")
        scenario.expectShows("square-1", "")
        scenario.expectShows("turn", "X's turn")
    }
}
